import{_ as r,y as s,a as c,o as l,a2 as n,D as i,g as a,I as t}from"./chunks/framework.DCcmcJcL.js";const b=JSON.parse('{"title":"Cache Management","description":"","frontmatter":{},"headers":[],"relativePath":"configure/cache-management.md","filePath":"configure/cache-management.md","lastUpdated":1787552929000}'),h={name:"configure/cache-management.md"};function g(d,e,p,u,f,m){const o=s("ImagePopup");return l(),c("div",null,[e[0]||(e[0]=n('<h1 id="cache-management" tabindex="-1">Cache Management <a class="header-anchor" href="#cache-management" aria-label="Permalink to &quot;Cache Management&quot;">​</a></h1><p>Cache Management allows the Admin to clear and rebuild various system caches to ensure that both the storefront and admin panel display the most up-to-date information while maintaining optimal performance.</p><p>To manage cache settings, go to the Admin Panel and navigate to <strong>Configure &gt;&gt; Cache Management</strong>.</p><h2 id="full-page-cache" tabindex="-1">Full Page Cache <a class="header-anchor" href="#full-page-cache" aria-label="Permalink to &quot;Full Page Cache&quot;">​</a></h2><p>Full Page Cache keeps a rendered copy of your storefront pages and serves that copy to the next visitor, instead of building the page again for every one of them. It is the setting that decides how quickly your storefront responds under load, and it is now controlled from the admin rather than by editing the server configuration.</p><p>Go to <strong>Configure &gt;&gt; Cache Management &gt;&gt; Full Page Cache</strong>.</p>',6)),i(o,{src:"/images/configure/full-page-cache.png",alt:"Full Page Cache settings"}),e[1]||(e[1]=n('<ul><li><strong>Enable Full Page Cache</strong> — when on, storefront pages are served from the cache. Turning it off makes every page render again on each visit, which is slower for shoppers but useful while you are diagnosing a page that looks stale.</li><li><strong>Cache Lifetime (Minutes)</strong> — how long a cached page is kept before it is built again. Leave it empty to use the store&#39;s default.</li></ul><p>Click <strong>Save Configuration</strong> to apply your changes.</p><h3 id="you-do-not-have-to-clear-it-after-an-edit" tabindex="-1">You do not have to clear it after an edit <a class="header-anchor" href="#you-do-not-have-to-clear-it-after-an-edit" aria-label="Permalink to &quot;You do not have to clear it after an edit&quot;">​</a></h3><p>A cached page is refreshed automatically when the content behind it changes. Editing a category or a product clears the pages that show it — your home page and category listings included — across every channel, locale and currency they were cached under. Publishing a section does the same for the storefront it belongs to.</p><p>So a lifetime is a backstop rather than the main mechanism. Set it long, and trust the automatic refresh for day-to-day edits.</p><p><strong>Note:</strong> A short lifetime is not a fix for a page that looks out of date. It only shortens how long the wrong page is shown. If a change is not appearing at all, clear the cache with the actions below and check the change was published.</p><h2 id="cache-actions" tabindex="-1">Cache Actions <a class="header-anchor" href="#cache-actions" aria-label="Permalink to &quot;Cache Actions&quot;">​</a></h2><p>The Cache Management section provides options to clear and rebuild different types of caches.</p><h3 id="clear-cache-options" tabindex="-1">Clear Cache Options <a class="header-anchor" href="#clear-cache-options" aria-label="Permalink to &quot;Clear Cache Options&quot;">​</a></h3><p>Use these actions to remove cached data and force the application to regenerate it on the next request.</p><ul><li><strong>Clear All Cache</strong> – Clears all available caches.</li><li><strong>Clear Config Cache</strong> – Removes cached configuration data.</li><li><strong>Clear Application Cache</strong> – Clears the application cache.</li><li><strong>Clear Compiled Cache</strong> – Removes compiled classes and files.</li><li><strong>Clear Event Cache</strong> – Clears cached event discovery data.</li><li><strong>Clear Route Cache</strong> – Removes cached route definitions.</li><li><strong>Clear View Cache</strong> – Clears compiled Blade view files.</li></ul><h3 id="build-cache-options" tabindex="-1">Build Cache Options <a class="header-anchor" href="#build-cache-options" aria-label="Permalink to &quot;Build Cache Options&quot;">​</a></h3><p>Use these actions to pre-build caches and improve application performance.</p><ul><li><strong>Rebuild All Cache</strong> – Rebuilds all supported caches.</li><li><strong>Cache Config</strong> – Generates configuration cache.</li><li><strong>Cache Routes</strong> – Generates route cache.</li><li><strong>Cache Views</strong> – Compiles and caches view files.</li></ul><h2 id="how-to-execute-cache-actions" tabindex="-1">How to Execute Cache Actions <a class="header-anchor" href="#how-to-execute-cache-actions" aria-label="Permalink to &quot;How to Execute Cache Actions&quot;">​</a></h2><p><strong>Step 1:</strong> Navigate to <strong>Configure &gt;&gt; Cache Management</strong>.</p><p><strong>Step 2:</strong> Click the desired cache action button under either <strong>Clear Cache</strong> or <strong>Build Cache</strong>.</p><p><strong>Step 3:</strong> Review the execution results in the <strong>Output Console</strong> section.</p><p><strong>Step 4:</strong> A success message and console output will be displayed once the operation is completed successfully.</p>',19)),i(o,{src:"/images/configure/cache-manage.png",alt:"Cache Management"}),e[2]||(e[2]=a("h2",{id:"important-notes",tabindex:"-1"},[t("Important Notes "),a("a",{class:"header-anchor",href:"#important-notes","aria-label":'Permalink to "Important Notes"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"Route caching will fail if any route file uses closures instead of controller references."),a("li",null,"Configuration caching will fail if any configuration file returns closures."),a("li",null,"File permission issues may prevent cache generation or cache clearing operations.")],-1)),e[4]||(e[4]=a("p",null,[t("⚠️ "),a("strong",null,"Note:"),t(" After clearing cache, the first few page loads may take slightly longer because the application needs to regenerate cached data. Rebuilding caches after deployment is recommended for better performance.")],-1))])}const y=r(h,[["render",g]]);export{b as __pageData,y as default};
